-- D12 written comment with the star rating: REVERT candidate. NOT APPLIED. It needs the owner's explicit "primeni" for THIS file (a revert of a privacy certification of the erasure program, AGENTS 3.1.4).
-- GENERATED by supabase/proofs/d12/build_d12.py from the pin tables of the DEV application, the read-only pre-image capture and this template: do not edit by hand (`--check` fails on any difference).
-- {{PROVENANCE}}
-- One atomic DO statement that returns the canonical DEV database to EXACTLY the state the ONE-statement application (d12_review_comment.sql) started from, or changes nothing:
--   * it runs only against the state that application produced (six rewritten bodies, six new functions, the table with its two triggers and two indexes, the catalog row, the roster tail, all pinned);
--   * it REFUSES while ANY comment row exists: removing user data is a separate owner decision, never a side effect of a revert (on DEV that is true as soon as the first comment exists);
--   * it REFUSES when ANY closure history names the comment table (a closure step of the relation `private.agreement_review_comments_v1`): after a closure ran, the closure ledger of that account names a relation that would no longer exist and
--     its step count would disagree with the roster (the Voice B1 revert refuses on its closure history for the same reason). So the revert window ends at the FIRST COMMENT or the FIRST CLOSURE after the application, whichever comes first;
--   * it restores the six pre-image definitions byte for byte (the captured text is embedded; the md5 of every restored body is asserted against the application's predecessor pin), restores the one retention-class description,
--     removes every object the application created (no CASCADE) and re-binds the closure certificate in its three places to the digest it had before the application, a digest the restored catalog must reproduce (otherwise it stops and reports);
--   * it never touches the star table (a hash of every review row is compared before and after), then proves the result: every predecessor pin of the application holds again, nothing else changed (functions, tables,
--     columns, constraints, triggers, policies, indexes, buckets, default ACLs), and the certificate is ready and bound.
do $d12_revert$
declare
  pin record; prior record; actual jsonb; before_surface jsonb; after_surface jsonb; expected_datasets jsonb; expected_classes jsonb; before_default_acls text; star_before text; star_after text;
  applied_source text; restored_source text; ready_definition text; affected integer; rewritten oid[]; new_functions oid[]; fresh oid[]; diff_keys text;
  target_source constant text := '{{CERTIFIED_DIGEST}}';
  surface_query text := $surface_query${{SURFACE_QUERY}}$surface_query$;
begin
  perform set_config('lock_timeout','5s',true);
  perform set_config('statement_timeout','120s',true);
  perform set_config('search_path','pg_catalog',true);
  if current_user<>'postgres' then raise exception 'D12_REVERT_OWNER_REQUIRED' using errcode='55000';end if;
  if to_regclass('private.{{TABLE}}') is null or to_regprocedure('{{SUBMIT_V2_SIGNATURE}}') is null then
    raise exception 'D12_REVERT_NOT_APPLIED' using errcode='55000';end if;
  -- Hold closure writes, review writes and comment writes until this atomic change commits (a fixed order, so a blocked statement times out instead of deadlocking).
  lock table private.closure_executions_v5 in share mode;
  lock table private.closure_source_v5,private.closure_erasure_source_v5,private.closure_dataset_catalog_v5 in share row exclusive mode;
  lock table private.agreement_reviews in share row exclusive mode;
  lock table private.retention_data_classes in share row exclusive mode;
  lock table private.{{TABLE}} in access exclusive mode;
  if exists(select 1 from private.closure_executions_v5 where state='EXECUTING') then
    raise exception 'D12_REVERT_CLOSURE_IN_FLIGHT' using errcode='55000';end if;
  if (select count(*) from private.closure_source_v5)<>1 or (select count(*) from private.closure_erasure_source_v5)<>1 then
    raise exception 'D12_REVERT_CERTIFICATE_CARDINALITY' using errcode='55000';end if;
  -- No user data is ever removed by this file.
  if exists(select 1 from private.{{TABLE}}) then
    raise exception 'D12_REVERT_COMMENTS_PRESENT' using errcode='55000';end if;
  -- ... and no closure history names the comment table (the revert would leave a ledger that names a dropped relation).
  if exists(select 1 from private.closure_redaction_steps_v5 where relation_name='private.{{TABLE}}') then
    raise exception 'D12_REVERT_CLOSURE_HISTORY_PRESENT' using errcode='55000';end if;
  -- The certificate is the one the application bound: certified in all three places, equal to the live digest, ready and bound.
  select sha256 into applied_source from private.closure_source_v5 where singleton;
  if applied_source is null or applied_source is distinct from private.closure_source_digest_v5()
     or applied_source is distinct from (select sha256 from private.closure_erasure_source_v5 where singleton)
     or private.retention_ai_source_ready() is distinct from true or private.closure_erasure_binding_v5()->>'sourceSha256' is distinct from applied_source then
    raise exception 'D12_REVERT_APPLIED_STATE_NOT_CERTIFIED' using errcode='55000';end if;
  if applied_source=target_source then raise exception 'D12_REVERT_ALREADY_AT_TARGET_DIGEST' using errcode='55000';end if;
  select pg_get_functiondef(p.oid) into ready_definition from pg_proc p where oid='private.retention_ai_source_ready()'::regprocedure;
  if not exists(select 1 from pg_proc where oid='private.retention_ai_source_ready()'::regprocedure
      and (length(prosrc)-length(replace(prosrc,applied_source,'')))=length(applied_source)
      and md5(replace(replace(prosrc,E'\r\n',E'\n'),applied_source,'__CERTIFIED_SOURCE__'))='{{READINESS_PLACEHOLDER_MD5}}')
     or (length(ready_definition)-length(replace(ready_definition,applied_source,'')))<>length(applied_source)
     or (select count(*) from regexp_matches(ready_definition,'[0-9a-f]{64}','g'))<>1 then
    raise exception 'D12_REVERT_READINESS_DRIFT' using errcode='55000';end if;
  -- The applied package, exactly: the six rewritten bodies (LF-normalised md5), the six new functions, the table, its two triggers, the catalog row, the roster tail and the export field.
  for pin in select * from (values
{{APPLIED_BODY_PINS}}
  ) p(signature,body_md5) loop
    if (select md5(replace(prosrc,E'\r\n',E'\n')) from pg_proc where oid=to_regprocedure(pin.signature)) is distinct from pin.body_md5 then
      raise exception 'D12_REVERT_APPLIED_BODY_DRIFT: %',pin.signature using errcode='55000';end if;
  end loop;
  for pin in select * from (values
{{NEW_FUNCTION_PINS}}
  ) p(signature,body_md5,language_name,volatility,definer,strict_function,result_type,acl) loop
    if not exists(select 1 from pg_proc p where p.oid=to_regprocedure(pin.signature) and {{NEW_FUNCTION_PREDICATE}}) then
      raise exception 'D12_REVERT_NEW_FUNCTION_DRIFT: %',pin.signature using errcode='55000';end if;
  end loop;
  if {{TABLE_SHAPE_BAD}} or {{TRIGGERS_BAD}} then
    raise exception 'D12_REVERT_APPLIED_STRUCTURE_DRIFT: table' using errcode='55000';end if;
  if (select description from private.retention_data_classes where code='{{RETENTION_CLASS_CODE}}' and required and active) is distinct from {{RETENTION_DESCRIPTION_NEW}} then
    raise exception 'D12_REVERT_RETENTION_CLASS_DRIFT' using errcode='55000';end if;
  if cardinality(private.closure_redaction_relations_v5())<>{{ROSTER_AFTER}}
     or (private.closure_redaction_relations_v5())[{{ROSTER_AFTER}}] is distinct from 'private.{{TABLE}}'
     or (select relations from private.closure_dataset_catalog_v5 where data_class='AGREEMENT_REVIEWS') is distinct from array['private.agreement_reviews','private.{{TABLE}}']::text[]
     or (select v->'fields' from jsonb_array_elements(private.data_export_dataset_catalog()) v where v->>'key'='ownAgreementReviews')
        is distinct from '["agreementId","createdAt","id","rating","tags","comment"]'::jsonb
     or private.data_export_projection_sha_v5() is distinct from '{{PROJECTION_SHA_AFTER}}' then
    raise exception 'D12_REVERT_APPLIED_STRUCTURE_DRIFT: roster, catalog or export' using errcode='55000';end if;

  -- What this change may touch: captured now, compared at the end.
  execute surface_query into before_surface;
  select string_agg(defaclnamespace::regnamespace::text||':'||defaclobjtype::text||':'||defaclacl::text,' | ' order by defaclnamespace::regnamespace::text,defaclobjtype::text) into before_default_acls from pg_default_acl;
  create temporary table d12_revert_functions on commit drop as
    select p.oid,p.oid::regprocedure::text signature,to_jsonb(p) metadata
    from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where n.nspname in('public','private','rls_private');
  select jsonb_agg(case when c.data_class='AGREEMENT_REVIEWS' then jsonb_set(to_jsonb(c),'{relations}',to_jsonb(array_remove(c.relations,'private.{{TABLE}}'))) else to_jsonb(c) end order by data_class)
    into expected_datasets from private.closure_dataset_catalog_v5 c;
  select md5(coalesce(string_agg(to_jsonb(r)::text,E'\n' order by r.id),'')) into star_before from private.agreement_reviews r;
  select jsonb_agg(case when c.code='{{RETENTION_CLASS_CODE}}' then jsonb_set(to_jsonb(c),'{description}',to_jsonb({{RETENTION_DESCRIPTION_OLD}}::text)) else to_jsonb(c) end order by c.code)
    into expected_classes from private.retention_data_classes c;
  rewritten:=array[{{REWRITTEN_ROSTER}}]::oid[];
  if cardinality(rewritten)<>{{REWRITTEN_COUNT}} or array_position(rewritten,null) is not null then raise exception 'D12_REVERT_REWRITTEN_ROSTER' using errcode='55000';end if;
  new_functions:=array[{{NEW_FUNCTION_ROSTER}}]::oid[];
  if cardinality(new_functions)<>{{NEW_FUNCTION_COUNT}} or array_position(new_functions,null) is not null then raise exception 'D12_REVERT_NEW_FUNCTION_ROSTER' using errcode='55000';end if;

  -- 1. The pre-image definitions (the six rewritten functions; the readiness function is re-bound below). The roster function goes first, so the digest never sees the table once it is dropped.
{{RESTORE_FUNCTIONS}}

  -- 2. The retention class text goes back to its predecessor text, and the retention catalog row loses the table before the table goes.
  update private.retention_data_classes set description={{RETENTION_DESCRIPTION_OLD}} where code='{{RETENTION_CLASS_CODE}}' and required and active and description={{RETENTION_DESCRIPTION_NEW}};
  get diagnostics affected=row_count;
  if affected<>1 then raise exception 'D12_REVERT_RETENTION_CLASS_ROW_COUNT' using errcode='55000';end if;
  update private.closure_dataset_catalog_v5 set relations=array_remove(relations,'private.{{TABLE}}') where data_class='AGREEMENT_REVIEWS';
  get diagnostics affected=row_count;
  if affected<>1 then raise exception 'D12_REVERT_CATALOG_ROW_COUNT' using errcode='55000';end if;

  -- 3. The new functions, then the table with its triggers and indexes, then the trigger function (nothing is dropped with CASCADE).
{{DROP_STATEMENTS}}

  -- 4. The certificate: the restored catalog must reproduce the pre-application digest; then the three places are bound to it.
  restored_source:=private.closure_source_digest_v5();
  if restored_source is distinct from target_source then
    raise exception 'D12_REVERT_DIGEST_NOT_RESTORED: % instead of %',restored_source,target_source using errcode='55000';end if;
  update private.closure_source_v5 set sha256=target_source where singleton and sha256=applied_source;
  get diagnostics affected=row_count;
  if affected<>1 then raise exception 'D12_REVERT_SOURCE_ROW_COUNT' using errcode='55000';end if;
  update private.closure_erasure_source_v5 set sha256=target_source where singleton and sha256=applied_source;
  get diagnostics affected=row_count;
  if affected<>1 then raise exception 'D12_REVERT_ERASURE_ROW_COUNT' using errcode='55000';end if;
  execute replace(ready_definition,applied_source,target_source);

  -- Delta accounting 1/3: every function is unchanged except the six restored ones (body only) and the readiness constant; the six new functions are gone and nothing new exists.
  for prior in select * from d12_revert_functions loop
    select to_jsonb(p) into actual from pg_proc p where oid=prior.oid;
    if prior.oid=any(new_functions) then
      if actual is not null then raise exception 'D12_REVERT_NEW_FUNCTION_REMAINS: %',prior.signature using errcode='55000';end if;
    elsif actual is null then raise exception 'D12_REVERT_FUNCTION_REMOVED: %',prior.signature using errcode='55000';
    elsif prior.oid='private.retention_ai_source_ready()'::regprocedure then
      if actual is distinct from jsonb_set(prior.metadata,'{prosrc}',to_jsonb(replace(prior.metadata->>'prosrc',applied_source,target_source))) then
        raise exception 'D12_REVERT_READINESS_DELTA' using errcode='55000';end if;
    elsif prior.oid=any(rewritten) then
      if actual-'prosrc' is distinct from prior.metadata-'prosrc' then
        raise exception 'D12_REVERT_FUNCTION_AUTHORITY_DELTA: %',prior.signature using errcode='55000';end if;
      if actual->>'prosrc' is not distinct from prior.metadata->>'prosrc' then
        raise exception 'D12_REVERT_RESTORE_MISSING: %',prior.signature using errcode='55000';end if;
    elsif actual is distinct from prior.metadata then
      raise exception 'D12_REVERT_UNRELATED_FUNCTION_DELTA: %',prior.signature using errcode='55000';
    end if;
  end loop;
  select coalesce(array_agg(p.oid order by p.oid),'{}'::oid[]) into fresh from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where n.nspname in('public','private','rls_private') and not exists(select 1 from d12_revert_functions old where old.oid=p.oid);
  if cardinality(fresh)<>0 then raise exception 'D12_REVERT_NEW_FUNCTION_DELTA' using errcode='55000';end if;
  -- The application's own predecessor pins hold again: metadata, then bodies (the six restored bodies included), then the projection sha.
  for pin in select * from (values
{{METADATA_PINS}}
  ) p(signature,metadata_md5) loop
    if (select md5(((to_jsonb(p)-'oid'-'pronamespace'-'proowner'-'prolang'-'proacl'-'prosrc')
        ||jsonb_build_object('namespace',n.nspname,'owner',pg_get_userbyid(p.proowner),
          'language',l.lanname,'acl',p.proacl::text))::text)
      from pg_proc p join pg_namespace n on n.oid=p.pronamespace join pg_language l on l.oid=p.prolang
      where p.oid=to_regprocedure(pin.signature)) is distinct from pin.metadata_md5 then
      raise exception 'D12_REVERT_METADATA_NOT_RESTORED: %',pin.signature using errcode='55000';end if;
  end loop;
  for pin in select * from (values
{{BODY_PINS}}
  ) p(signature,body_md5) loop
    if (select md5(replace(prosrc,E'\r\n',E'\n')) from pg_proc where oid=to_regprocedure(pin.signature)) is distinct from pin.body_md5 then
      raise exception 'D12_REVERT_BODY_NOT_RESTORED: %',pin.signature using errcode='55000';end if;
  end loop;
  if not exists(select 1 from pg_proc where oid='private.retention_ai_source_ready()'::regprocedure
      and (length(prosrc)-length(replace(prosrc,target_source,'')))=length(target_source)
      and md5(replace(replace(prosrc,E'\r\n',E'\n'),target_source,'__CERTIFIED_SOURCE__'))='{{READINESS_PLACEHOLDER_MD5}}') then
    raise exception 'D12_REVERT_READINESS_NOT_RESTORED' using errcode='55000';end if;
  if private.data_export_projection_sha_v5() is distinct from '{{PROJECTION_SHA_BEFORE}}' then
    raise exception 'D12_REVERT_PROJECTION_SHA_NOT_RESTORED' using errcode='55000';end if;

  -- Delta accounting 2/3: every table, column, constraint, trigger, policy, index and bucket is what it was before the application.
  execute surface_query into after_surface;
  if after_surface is distinct from before_surface then
    select string_agg(k||': +'||(select count(*) from jsonb_array_elements(coalesce(after_surface->k,'[]'::jsonb)) e where not(coalesce(before_surface->k,'[]'::jsonb) @> jsonb_build_array(e)))::text
      ||' -'||(select count(*) from jsonb_array_elements(coalesce(before_surface->k,'[]'::jsonb)) e where not(coalesce(after_surface->k,'[]'::jsonb) @> jsonb_build_array(e)))::text
      ||' added '||coalesce((select left(e::text,240) from jsonb_array_elements(coalesce(after_surface->k,'[]'::jsonb)) e where not(coalesce(before_surface->k,'[]'::jsonb) @> jsonb_build_array(e)) limit 1),'-')
      ||' removed '||coalesce((select left(e::text,240) from jsonb_array_elements(coalesce(before_surface->k,'[]'::jsonb)) e where not(coalesce(after_surface->k,'[]'::jsonb) @> jsonb_build_array(e)) limit 1),'-'),' | ')
      into diff_keys from jsonb_object_keys(before_surface) k where before_surface->k is distinct from after_surface->k;
    raise exception 'D12_REVERT_UNRELATED_CATALOG_DELTA: %',diff_keys using errcode='55000';
  end if;
  if (select string_agg(defaclnamespace::regnamespace::text||':'||defaclobjtype::text||':'||defaclacl::text,' | ' order by defaclnamespace::regnamespace::text,defaclobjtype::text) from pg_default_acl) is distinct from before_default_acls then
    raise exception 'D12_REVERT_DEFAULT_ACL_DELTA' using errcode='55000';end if;
  if to_regclass('private.{{TABLE}}') is not null
     or exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where (n.nspname,p.proname) in({{NEW_FUNCTION_NAME_PAIRS}}))
     or exists(select 1 from pg_trigger where tgname in({{TRIGGER_NAME_LIST}}))
     or exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='private' and c.relname in({{INDEX_NAME_LIST}}))
     or exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in('public','private','rls_private') and c.relname like 'agreement\_review\_comment%') then
    raise exception 'D12_REVERT_NEW_OBJECT_REMAINS' using errcode='55000';end if;

  -- Delta accounting 3/3: the retention catalog is what it was, the star table is untouched, the certificate is bound in its three places to the restored digest, nothing else moved.
  if (select jsonb_agg(to_jsonb(c) order by data_class) from private.closure_dataset_catalog_v5 c) is distinct from expected_datasets then
    raise exception 'D12_REVERT_CATALOG_DELTA' using errcode='55000';end if;
  if (select jsonb_agg(to_jsonb(c) order by c.code) from private.retention_data_classes c) is distinct from expected_classes
     or (select count(*) from private.retention_data_classes where required and active)<>15 then
    raise exception 'D12_REVERT_RETENTION_CLASSES_DELTA' using errcode='55000';end if;
  select md5(coalesce(string_agg(to_jsonb(r)::text,E'\n' order by r.id),'')) into star_after from private.agreement_reviews r;
  if star_after is distinct from star_before then raise exception 'D12_REVERT_STAR_DATA_DELTA' using errcode='55000';end if;
  if cardinality(private.closure_redaction_relations_v5())<>{{ROSTER_BEFORE}}
     or (select v->'fields' from jsonb_array_elements(private.data_export_dataset_catalog()) v where v->>'key'='ownAgreementReviews')
        is distinct from '["agreementId","createdAt","id","rating","tags"]'::jsonb then
    raise exception 'D12_REVERT_CLOSURE_OR_EXPORT_NOT_RESTORED' using errcode='55000';end if;
  if private.closure_source_digest_v5() is distinct from target_source
     or (select sha256 from private.closure_source_v5 where singleton) is distinct from target_source
     or (select sha256 from private.closure_erasure_source_v5 where singleton) is distinct from target_source
     or private.retention_ai_source_ready() is distinct from true
     or private.closure_erasure_binding_v5()->>'sourceSha256' is distinct from target_source then
    raise exception 'D12_REVERT_CERTIFIED_POSTCONDITION' using errcode='55000';end if;
  if exists(select 1 from private.closure_executions_v5 where state='EXECUTING')
     or has_function_privilege('anon','private.retention_ai_source_ready()','EXECUTE')
     or has_function_privilege('authenticated','private.retention_ai_source_ready()','EXECUTE') then
    raise exception 'D12_REVERT_FINAL_AUTHORITY_OR_STATE_DRIFT' using errcode='55000';end if;
  perform pg_notify('pgrst','reload schema');
end
$d12_revert$;
